export function renderLanding(config: BusinessConfig): string {
  const ticker = `YOUR NUMBER&nbsp;&nbsp;·&nbsp;&nbsp;YOUR HOURS&nbsp;&nbsp;·&nbsp;&nbsp;YOUR SERVICE AREA&nbsp;&nbsp;·&nbsp;&nbsp;YOUR RULES&nbsp;&nbsp;·&nbsp;&nbsp;NO ENTERPRISE RUNAROUND&nbsp;&nbsp;·&nbsp;&nbsp;`;
  return publicLayout("AI Front Office", `<div class="announcement">Built for solo HVAC owners and small crews</div>
    <header class="publicnav"><a class="brand" href="/" aria-label="AI Front Office home"><span>Front</span> Office</a><nav><a href="#how-it-works">How it works</a><a href="#compare">Compare</a><a href="#pricing">Pricing</a><a href="/demo">Dashboard demo</a><a href="/login">Sign in</a><a class="navbutton" href="/signup">Cover my calls</a></nav></header>
    <main class="publicmain">
      <section class="publichero"><div class="hero-copy"><p class="eyebrow">The AI receptionist built for the truck</p><h1 aria-label="When you’re on a job, we answer the phone.">When you’re on a job, <em>we answer the phone.</em></h1><p class="lede">Your phone rings first. If you miss it—or it’s after hours—Front Office answers, captures the job, checks your rules, and texts you the details.</p><div class="actions"><a class="button" href="/signup">Cover my calls</a><a class="textlink" href="/demo">Open the dashboard demo</a></div><p class="small">Keep your number. Set your own hours. Pause anytime.</p></div><div class="mascot-stage"><img src="/assets/front-office-mascot-flat.png" width="320" height="338" alt="A friendly phone-shaped front-office helper in a hard hat"><p class="mascot-bubble">Missed call? I’ve got it.</p><div class="mini-receipt"><strong>No heat. Family home.</strong><span>Number confirmed · Owner alerted</span></div></div></section>
      <div class="ticker" aria-label="Product highlights"><div class="ticker-track"><span>${ticker}</span><span aria-hidden="true">${ticker}</span></div></div>
      <section id="how-it-works" class="publicsection"><p class="eyebrow">Clocked in when you can’t be</p><h2>A backup front desk that actually does the work.</h2><div class="feature-grid"><article><span class="number">01</span><h3>Answers</h3><p>Your greeting. Clear AI disclosure. Caller name, number, address, and problem captured without making them repeat the number they called from.</p></article><article class="yellow"><span class="number">02</span><h3>Sorts</h3><p>Urgent calls jump the line. Routine work is checked against the service area, hours, prices, and Google Calendar you control.</p></article><article class="red"><span class="number">03</span><h3>Shows its work</h3><p>You get the recording, transcript, urgency, job details, and honest booking status. Spam minutes are excluded.</p></article></div></section>
      <section class="publicsection rules"><div><p class="eyebrow">Your shop. Your rules.</p><h2>You control the whole front desk.</h2></div><div><p>Set coverage hours, service area, emergency rules, approved prices, answers, and appointment windows yourself. Front Office never diagnoses equipment, invents a price, or says a job is booked before the calendar confirms it.</p></div></section>
      <section id="compare" class="publicsection compare"><p class="eyebrow">The right-sized fix</p><h2>Don’t buy a call center to catch a missed call.</h2><div class="feature-grid"><article class="yellow"><span class="number">FRONT OFFICE</span><h3>Answers + organizes</h3><p><strong>$${Math.round(config.flatMonthlyPriceCents / 100)}/month.</strong><br>Your number rings first.<br>Your rules and calendar.<br>Recording, transcript, and owner alert.<br>Built for 1–10-person shops.</p></article><article><span class="number">VOICEMAIL</span><h3>Records a message</h3><p><strong>No new software.</strong><br>You call back later.<br>No service-area check.<br>No emergency sorting.<br>No calendar write.</p></article><article class="red"><span class="number">LARGER AI SUITE</span><h3>More than most small shops need</h3><p><strong>Broader workflows.</strong><br>More integrations.<br>More setup.<br>Useful when you need a full call-center stack.</p></article></div><p class="lede"><strong>Five-person shop?</strong> Keep one public number and choose one owner or dispatcher to receive alerts. Team logins and rotating on-call alerts are not included yet.</p></section>
      <section class="publicsection steps"><p class="eyebrow">Start without a sales call</p><h2>Set up the shop yourself. Get help if you want it.</h2><ol><li><strong>Create your shop.</strong><span>Enter your own hours, ZIP codes, greeting, emergency rules, and alert number.</span></li><li><strong>Connect billing + calendar.</strong><span>Checkout and Google authorization happen from the owner dashboard. The carrier line remains paused until its safety checks pass.</span></li><li><strong>Forward missed calls.</strong><span>Early shops get hands-on line activation; every setting remains yours to change later.</span></li></ol></section>
      <section id="pricing" class="publicsection pricing"><div><p class="eyebrow">Solo + small crew</p><h2>$${Math.round(config.flatMonthlyPriceCents / 100)}<span>/month</span></h2></div><div><p><strong>${config.includedMinutes} connected AI minutes included—about 50 four-minute calls.</strong> Then $${(config.overageCentsPerMinute / 100).toFixed(2)}/minute. Spam is excluded. Line setup, owner alerts, recordings, transcripts, emergency triage, service-area checks, and Google Calendar are included.</p><a class="button" href="/signup">Create my shop</a><p class="small">One account can cover the shared public line for a five-person shop. There is no per-employee charge.</p></div></section>
      <section id="faq" class="publicsection faq"><p class="eyebrow">Straight answers</p><h2>Before you hand over a missed call.</h2><details><summary>Do I keep my current phone number?</summary><p>Yes. Forward only missed, overflow, or after-hours calls to the line we provision.</p></details><details><summary>Can my five-person shop use one plan?</summary><p>Yes. The plan covers one shared public line and one owner or dispatcher alert destination today. It is not priced per employee.</p></details><details><summary>Does it pretend to be human?</summary><p>No. The greeting identifies it as the owner’s AI assistant and uses your approved recording language.</p></details><details><summary>Can it book jobs?</summary><p>Only when your connected Google Calendar confirms the write. Otherwise it queues the request and tells the caller that the shop will confirm.</p></details><details><summary>What happens after ${config.includedMinutes} minutes?</summary><p>Usage continues at $${(config.overageCentsPerMinute / 100).toFixed(2)} per connected minute. Provider-classified spam is excluded.</p></details></section>
      <footer class="publicfooter"><span>AI Front Office for home-service shops</span><div><a href="/privacy">Privacy</a><a href="/terms">Terms</a><a href="/login">Owner sign in</a></div></footer>
    </main>`);
}

export function renderOwnerSignup(error = "", values: Record<string, string> = {}): string {
  const value = (name: string, fallback = ""): string => escapeHtml(values[name] ?? fallback);
  return publicLayout("Create your shop", `<div class="announcement">Your shop settings—not ours</div><header class="publicnav"><a class="brand smallbrand" href="/"><span>Front</span> Office</a><nav><a href="/login">Already have an account?</a></nav></header><main class="publicmain formpage"><section class="formintro"><p class="eyebrow">Owner setup</p><h1>Tell the front desk how your shop works.</h1><p>You control the hours, service area, emergency rules, and alert number. Complete setup anytime; the carrier line stays paused until its final activation checks pass.</p></section>${error ? `<p class="formerror">${escapeHtml(error)}</p>` : ""}<form class="publicform" method="post" action="/signup"><div class="grid two"><label>Your name<input name="displayName" autocomplete="name" maxlength="120" value="${value("displayName")}" required></label><label>Business name<input name="businessName" autocomplete="organization" maxlength="120" value="${value("businessName")}" required></label></div><div class="grid two"><label>Email<input name="email" type="email" autocomplete="email" maxlength="254" value="${value("email")}" required></label><label>Password<input name="password" type="password" autocomplete="new-password" minlength="12" maxlength="200" required><span class="small">At least 12 characters.</span></label></div><div class="grid two"><label>Owner alert phone<input name="phone" type="tel" autocomplete="tel" inputmode="tel" maxlength="30" value="${value("phone")}" required></label><label>Timezone<select name="timezone">${selectOption("America/New_York", "Eastern", values.timezone)}${selectOption("America/Chicago", "Central", values.timezone)}${selectOption("America/Denver", "Mountain", values.timezone)}${selectOption("America/Phoenix", "Arizona", values.timezone)}${selectOption("America/Los_Angeles", "Pacific", values.timezone)}</select></label></div><label>Covered cities + states and ZIP codes<input name="serviceAreaTerms" maxlength="800" placeholder="Albany NY, 12207, 12208" value="${value("serviceAreaTerms")}" required></label><div class="grid two"><label>When should Front Office answer?<select name="operationMode">${selectOption("overflow", "When I miss the call", values.operationMode)}${selectOption("after_hours", "After hours and weekends", values.operationMode)}${selectOption("always", "Every call", values.operationMode)}</select></label><label>Greeting<input name="greeting" maxlength="500" value="${value("greeting")}" placeholder="Thanks for calling..." required></label></div><div class="grid two"><label>After-hours coverage starts<input name="weekdayStart" type="time" value="${value("weekdayStart", "17:00")}" required></label><label>After-hours coverage ends<input name="weekdayEnd" type="time" value="${value("weekdayEnd", "08:00")}" required></label></div><div class="grid two"><label>Appointments start<input name="bookableWeekdayStart" type="time" value="${value("bookableWeekdayStart", "08:00")}" required></label><label>Appointments end<input name="bookableWeekdayEnd" type="time" value="${value("bookableWeekdayEnd", "17:00")}" required></label></div><label>Services you handle<input name="serviceCategories" maxlength="800" value="${value("serviceCategories", "HVAC repair, HVAC maintenance")}" required></label><label>Emergency words or situations<input name="emergencyKeywords" maxlength="800" value="${value("emergencyKeywords", "gas smell, carbon monoxide, no heat, frozen pipes")}" required></label><label class="check"><input name="weekends" type="checkbox" ${values.weekends === "on" ? "checked" : ""}> Cover weekends</label><label class="trap" aria-hidden="true">Fax number<input name="faxNumber" tabindex="-1" autocomplete="off"></label><label class="check"><input name="ownerSmsConsent" type="checkbox" value="yes" ${values.ownerSmsConsent === "yes" ? "checked" : ""} required> Send operational call alerts from Front Office to this number. Message frequency varies; message and data rates may apply. Reply STOP to opt out or HELP for help. See <a href="/terms">Terms</a> and <a href="/privacy">Privacy</a>.</label><label class="check"><input name="founderSmsConsent" type="checkbox" value="yes" ${values.founderSmsConsent === "yes" ? "checked" : ""}> Text me one welcome message from the founder at this number. Optional; reply STOP to opt out.</label><label class="check"><input name="consent" type="checkbox" value="yes" required> I agree to the <a href="/terms">terms</a> and <a href="/privacy">privacy notice</a>.</label><button>Create my shop</button></form></main>`);
}

